<?php require __DIR__.'/../config.php';if(admin()){header('Location:index.php');exit;}$err='';if($_SERVER['REQUEST_METHOD']==='POST'){try{check_csrf();$st=db()->prepare('SELECT * FROM admins WHERE email=?');$st->execute([trim($_POST['email']??'')]);$a=$st->fetch();if(!$a||!password_verify($_POST['password']??'',$a['password_hash']))throw new RuntimeException('Invalid email or password.');session_regenerate_id(true);$_SESSION['admin_id']=$a['id'];$_SESSION['admin_name']=$a['name'];header('Location:index.php');exit;}catch(Throwable $e){$err=$e->getMessage();}}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="admin.css"><title>Admin Login</title></head><body class="login"><div class="panel"><h1>Admin Login</h1><?php if($err):?><div class="alert"> <?=e($err)?></div><?php endif;?><form method="post" class="form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Email<input type="email" name="email" value="<?=e($_POST['email']??ADMIN_EMAIL)?>" required></label><label>Password<input type="password" name="password" required></label><button class="btn primary" type="submit">Sign in</button></form><p class="muted">First login password: <b>password</b>. Change it immediately.</p></div></body></html>
